function BookEdgeColoringSpongeMaker.init() BookEdgeColoringSpongeMaker.ironStock=10; BookEdgeColoringSpongeMaker.bronzeStock=8; BookEdgeColoringSpongeMaker.woodStock=14; BookEdgeColoringSpongeMaker.leatherStock=14; BookEdgeColoringSpongeMaker.silverStock=8; BookEdgeColoringSpongeMaker.goldStock=6; BookEdgeColoringSpongeMaker.jewelStock=4; BookEdgeColoringSpongeMaker.pearlStock=4; BookEdgeColoringSpongeMaker.productStock={}; BookEdgeColoringSpongeMaker.buildings={}; BookEdgeColoringSpongeMaker.maker=nil; BookEdgeColoringSpongeMaker.activeMaking={}; BookEdgeColoringSpongeMaker.totalProducts=0; BookEdgeColoringSpongeMaker.dayTimer=0; print("[BookEdgeColoringSpongeMaker] Royal Book Edge Coloring Sponge Maker System initialized (6 products, 4 buildings)") end
function BookEdgeColoringSpongeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookEdgeColoringSpongeMaker.maker={name=n or ("Gobar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gobar najet: %s (spretnost: %d)",BookEdgeColoringSpongeMaker.maker.name,s),"success") end; return true end
function BookEdgeColoringSpongeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookEdgeColoringSpongeMaker.build(id) local ok,e=BookEdgeColoringSpongeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookEdgeColoringSpongeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookEdgeColoringSpongeMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookEdgeColoringSpongeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookEdgeColoringSpongeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookEdgeColoringSpongeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookEdgeColoringSpongeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookEdgeColoringSpongeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookEdgeColoringSpongeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookEdgeColoringSpongeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookEdgeColoringSpongeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookEdgeColoringSpongeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookEdgeColoringSpongeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookEdgeColoringSpongeMaker.buildings==0 then return false,"Potrebna gobna delavnica" end; if not BookEdgeColoringSpongeMaker.maker then return false,"Potreben gobar" end; return true end
function BookEdgeColoringSpongeMaker.make(pt,qty) qty=qty or 1; local ok,e=BookEdgeColoringSpongeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookEdgeColoringSpongeMaker.ironStock=BookEdgeColoringSpongeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookEdgeColoringSpongeMaker.bronzeStock=BookEdgeColoringSpongeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookEdgeColoringSpongeMaker.woodStock=BookEdgeColoringSpongeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookEdgeColoringSpongeMaker.leatherStock=BookEdgeColoringSpongeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookEdgeColoringSpongeMaker.silverStock=BookEdgeColoringSpongeMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookEdgeColoringSpongeMaker.goldStock=BookEdgeColoringSpongeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookEdgeColoringSpongeMaker.jewelStock=BookEdgeColoringSpongeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookEdgeColoringSpongeMaker.pearlStock=BookEdgeColoringSpongeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookEdgeColoringSpongeMaker.maker then t=math.max(1,t-math.floor(BookEdgeColoringSpongeMaker.maker.skill/13)) end; table.insert(BookEdgeColoringSpongeMaker.activeMaking,{id="bookedgecoloringsponge_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookEdgeColoringSpongeMaker.completeMaking(m) local q=1.0+(BookEdgeColoringSpongeMaker.getQualityBonus()/100); if BookEdgeColoringSpongeMaker.maker then q=q+(BookEdgeColoringSpongeMaker.maker.skill/140) end; q=math.min(2.5,q); BookEdgeColoringSpongeMaker.productStock[m.productType]=(BookEdgeColoringSpongeMaker.productStock[m.productType] or 0)+m.quantity; BookEdgeColoringSpongeMaker.totalProducts=BookEdgeColoringSpongeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookEdgeColoringSpongeMaker.maker then BookEdgeColoringSpongeMaker.maker.itemsMade=BookEdgeColoringSpongeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookEdgeColoringSpongeMaker.maker.skill=math.min(100,BookEdgeColoringSpongeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Goba izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookedgecoloringsponge.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookEdgeColoringSpongeMaker.update(dt) if not _G.state then return end; BookEdgeColoringSpongeMaker.dayTimer=BookEdgeColoringSpongeMaker.dayTimer+dt; if BookEdgeColoringSpongeMaker.dayTimer>=30 then BookEdgeColoringSpongeMaker.dayTimer=0; for i=#BookEdgeColoringSpongeMaker.activeMaking,1,-1 do local m=BookEdgeColoringSpongeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookEdgeColoringSpongeMaker.completeMaking(m); table.remove(BookEdgeColoringSpongeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookEdgeColoringSpongeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookEdgeColoringSpongeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
